import{_ as t,c as e,a2 as l,o as c}from"./chunks/framework.CO0qOYmW.js";const u=JSON.parse('{"title":"HTML面试题","description":"","frontmatter":{},"headers":[],"relativePath":"interview/index.md","filePath":"interview/index.md","lastUpdated":1754328688000}'),i={name:"interview/index.md"};function a(s,o,d,r,n,p){return c(),e("div",null,o[0]||(o[0]=[l('<h1 id="html面试题" tabindex="-1">HTML面试题 <a class="header-anchor" href="#html面试题" aria-label="Permalink to &quot;HTML面试题&quot;">​</a></h1><h2 id="_1、html5有哪些新特性" tabindex="-1">1、html5有哪些新特性 <a class="header-anchor" href="#_1、html5有哪些新特性" aria-label="Permalink to &quot;1、html5有哪些新特性&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">html5新特性</p><p></p><ol><li>文档声明：<code>&lt;!DOCTYPE&gt;</code></li><li>语义化标签：结构更清晰，利于SEO。</li><li>多媒体支持：<code>video</code> 和 <code>audio</code> 元素。</li><li>图形处理：<code>canvas</code> 元素用于绘制图形和动画。</li><li>表单控件增强：<code>color</code>、<code>date</code>、<code>time</code>、<code>email</code>、<code>url</code>、<code>search</code>;</li><li>本地离线存储: <code>localStorage</code> 和 <code>sessionStorage</code> 客户端存储数据，比 cookie 存储更安全;</li><li>新技术:<code>web worker</code>, <code>websocket</code>, <code>Geolocation(定位)</code>;</li></ol></div><h2 id="_2、src-和-href-属性的区别" tabindex="-1">2、src 和 href 属性的区别 <a class="header-anchor" href="#_2、src-和-href-属性的区别" aria-label="Permalink to &quot;2、src 和 href 属性的区别&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">1. 应用标签不同</p><p></p><ol><li><code>src</code> : <strong>指定要加载的资源路径</strong>，常出现于 <code>&lt;script&gt;</code>、<code>&lt;img&gt;</code>、<code>&lt;audio&gt;</code>、<code>&lt;video&gt;</code> 和 <code>&lt;iframe&gt;</code> 等标签中，用于加载 JavaScript 脚本、图像、音频、视频或嵌入的网页文件。</li><li><code>href</code> : <strong>指定超链接的目标地址</strong>或定义文档与外部资源的关联，主要用在 <code>&lt;a&gt;</code>、<code>&lt;link&gt;</code>、<code>&lt;area&gt;</code> 等标签中</li></ol></div><div class="tip custom-block github-alert"><p class="custom-block-title">2. 资源加载方式不同</p><p></p><ol><li><code>src</code>:当浏览器解析到适用于<code>src</code> 属性的标签时，会<strong>暂停其他资源</strong>的下载和处理，直到将该资源加载、编译、执⾏完成。这种方式称为<strong>阻塞加载</strong>,所以⼀般建议将 JavaScript 脚本放在页面底部。</li><li><code>href</code>:当浏览器识别到适用于 <code>href</code> 属性的标签时，会<strong>并⾏下载</strong>资源，不会停⽌对当前⽂档的处理。这种方式称为<strong>非阻塞加载</strong>，浏览器可以同时处理超链接或引入样式表。</li></ol></div><h2 id="_3、canvas-和-svg-的区别" tabindex="-1">3、Canvas 和 SVG 的区别 <a class="header-anchor" href="#_3、canvas-和-svg-的区别" aria-label="Permalink to &quot;3、Canvas 和 SVG 的区别&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">概述</p><p><code>Canvas</code> 和 <code>SVG</code> 都是用于在<strong>网页上绘制图形的技术</strong>，但它们在实现方式、性能和使用场景上有明显的区别。</p><ul><li><code>Canvas</code> <strong>是基于像素的即时绘制技术</strong>，适合频繁更新和复杂动画，</li><li><code>SVG</code> <strong>是基于矢量的图形格式</strong>，适合需要无损缩放和高分辨率的静态图形。</li></ul></div><h3 id="_3-1、-具体区别" tabindex="-1">3.1、 具体区别 <a class="header-anchor" href="#_3-1、-具体区别" aria-label="Permalink to &quot;3.1、 具体区别&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">渲染方式</p><p></p><ul><li><code>Canvas</code>：逐像素渲染，适合实时动态绘制。</li><li><code>SVG</code>：基于矢量描述，适合静态和简单的动态绘制。</li></ul></div><div class="tip custom-block github-alert"><p class="custom-block-title">性能</p><p></p><ul><li><code>Canvas</code>：高性能，适合频繁更新的图形和复杂动画。</li><li><code>SVG</code>：在处理复杂图形时，性能可能会下降。</li></ul></div><div class="tip custom-block github-alert"><p class="custom-block-title">交互和 DOM 集成</p><p></p><ul><li><code>Canvas</code>：不具备内置的 DOM 交互，需要额外的事件处理代码。</li><li><code>SVG</code>：每个图形元素都是 DOM 节点，天然支持交互和事件处理。</li></ul></div><h3 id="_3-2、特点及优缺点" tabindex="-1">3.2、特点及优缺点 <a class="header-anchor" href="#_3-2、特点及优缺点" aria-label="Permalink to &quot;3.2、特点及优缺点&quot;">​</a></h3><div class="tip custom-block github-alert"><p class="custom-block-title">特点</p><p></p><ol><li><strong>基于像素</strong>：Canvas 绘图是逐像素操作，类似于在位图画布上绘制。</li><li><strong>即刻渲染</strong>：一旦图形绘制完成，就无法直接访问或修改其内容，除非重新绘制。</li><li><strong>不具备DOM特性</strong>：绘制在 Canvas 上的图形不是 DOM 元素，不能通过 DOM 直接访问和修改。</li><li><strong>动态绘图</strong>：非常适合需要频繁更新和复杂图形操作的应用，如游戏、动态数据可视化等。</li></ol></div><div class="tip custom-block github-alert"><p class="custom-block-title">优点</p><p></p><ol><li><strong>高性能</strong>：对于频繁变化和复杂的动画，Canvas 提供了较高的性能。</li><li><strong>细粒度控制</strong>：通过 JavaScript API，可以对每个像素进行精确控制，适用于精细的图形绘制。</li><li><strong>适合实时渲染</strong>：能高效处理大批量图形的实时渲染。</li></ol></div><div class="tip custom-block github-alert"><p class="custom-block-title">缺点</p><p></p><ol><li><strong>无法缩放</strong>：因为是基于像素的图形，缩放时可能失真。</li><li><strong>无内置交互</strong>：需要额外编写代码来处理用户交互。</li><li><strong>复杂性</strong>：处理复杂图形时，代码量和复杂度较高。</li></ol></div>',16)]))}const h=t(i,[["render",a]]);export{u as __pageData,h as default};
